insert into public.idioms (spanish, english, example, source_url) values
  ('tirar los tejos', 'to flirt with someone, to hit on someone', '«¿Se puede saber qué os pasa?» «Nada, que aquí el amigo ha intentado tirarle los tejos a tu novia.»', 'https://en.wiktionary.org/wiki/tirar_los_tejos#Spanish'), -- example: tatoeba.org/sentences/1539735 (Shishir)
  ('vete con la música a otra parte', 'scram; get outta here; go take a long walk off a short pier', '¡Vete con la música a otra parte y déjanos en paz de una vez!', 'https://en.wiktionary.org/wiki/vete_con_la_música_a_otra_parte#Spanish'), -- example: tatoeba.org/sentences/3720367 (Seael)
  ('el tiempo es oro', 'time is money', 'Mi padre solía decir que el tiempo es oro.', 'https://en.wiktionary.org/wiki/el_tiempo_es_oro#Spanish'), -- example: tatoeba.org/sentences/1508358 (marcelostockle)
  ('rizar el rizo', 'to gild the lily, to overcomplicate matters', 'Eso ya es rizar el rizo.', 'https://en.wiktionary.org/wiki/rizar_el_rizo#Spanish'), -- example: tatoeba.org/sentences/1388390 (enteka)
  ('a fin de cuentas', 'at the end of the day', 'Su razonamiento es atractivo, pero a fin de cuentas falaz.', 'https://en.wiktionary.org/wiki/a_fin_de_cuentas#Spanish'), -- example: tatoeba.org/sentences/950926 (darinmex)
  ('ponerse al corriente', 'to get in the loop; to clue oneself up; to find out', 'No me pusieron al corriente de que Tom hablaba francés.', 'https://en.wiktionary.org/wiki/ponerse_al_corriente#Spanish'), -- example: tatoeba.org/sentences/11883254 (JSKabylie15)
  ('echar la culpa', 'to blame; to lay/put the blame (on)', 'Supongo que necesito alguien a quien echarle la culpa.', 'https://en.wiktionary.org/wiki/echar_la_culpa#Spanish'), -- example: tatoeba.org/sentences/2106346 (lazarus1907)
  ('vérsele el plumero', 'to be blindingly obvious', 'No habían pasado ni dos horas y al concurso ya se le veía el plumero.', 'https://en.wiktionary.org/wiki/vérsele_el_plumero#Spanish'), -- example: Wiktionary
  ('dar en la nariz', 'to be suspicious, to give (someone) a feeling', 'Me da en la nariz que ni Anita ni Lucía están ocupadas.', 'https://en.wiktionary.org/wiki/dar_en_la_nariz#Spanish'), -- example: tatoeba.org/sentences/13704431 (Seael)
  ('pasarse la vida', 'to be forever doing (something)', 'Se pasa la vida viendo la tele.', 'https://en.wiktionary.org/wiki/pasarse_la_vida#Spanish'), -- example: Wiktionary
  ('cara o cruz', 'heads or tails', 'Tom lanzó la moneda y preguntó "¿cara o cruz?"', 'https://en.wiktionary.org/wiki/cara_o_cruz#Spanish'), -- example: tatoeba.org/sentences/2762278 (Shishir)
  ('pensar dos veces', 'to think twice', 'Debería pensarlo dos veces antes de abordar los botes.', 'https://en.wiktionary.org/wiki/pensar_dos_veces#Spanish'), -- example: tatoeba.org/sentences/9764438 (Eremon)
  ('tener algo que ver con', 'to have something to do with, to concern, to have some relationship with', 'Intuyo que la noticia tiene algo que ver con el caso.', 'https://en.wiktionary.org/wiki/tener_algo_que_ver_con#Spanish'), -- example: tatoeba.org/sentences/13066795 (Stuhr)
  ('tener en mente', 'to bear in mind', 'Tengo en mente dos objetivos de los cuales no desistiré.', 'https://en.wiktionary.org/wiki/tener_en_mente#Spanish'), -- example: tatoeba.org/sentences/1526337 (hayastan)
  ('dejar en paz', 'to leave alone', '¡Dejame en paz!, no ves que estoy intentando trabajar.', 'https://en.wiktionary.org/wiki/dejar_en_paz#Spanish'), -- example: tatoeba.org/sentences/5053717 (don_ramon)
  ('coser y cantar', 'a piece of cake, a breeze', 'Una vez que le cojas el tranquillo será coser y cantar.', 'https://en.wiktionary.org/wiki/coser_y_cantar#Spanish'), -- example: tatoeba.org/sentences/7848652 (Seael)
  ('la paciencia es una virtud', 'patience is a virtue', 'La paciencia es una virtud que no cualquiera tiene.', 'https://en.wiktionary.org/wiki/la_paciencia_es_una_virtud#Spanish'), -- example: tatoeba.org/sentences/1501282 (marcelostockle)
  ('dejarse en el tintero', 'to forget about something; to have something slip one''s mind', '¿Acaso te has dejado algo en el tintero?', 'https://en.wiktionary.org/wiki/dejarse_en_el_tintero#Spanish'), -- example: tatoeba.org/sentences/13471323 (Seael)
  ('dar tiempo al tiempo', 'to let time take its course', 'Hay que darle tiempo al tiempo.', 'https://en.wiktionary.org/wiki/dar_tiempo_al_tiempo#Spanish'), -- example: tatoeba.org/sentences/854116 (macronoid)
  ('romper una lanza', 'to stand up (for), to break a lance (for)', 'Tengo que romper una lanza en favor de Ludmila e Igor.', 'https://en.wiktionary.org/wiki/romper_una_lanza#Spanish'), -- example: tatoeba.org/sentences/10185731 (Seael)
  ('echar por tierra', 'to debunk', 'Cuando tengas una cita cuida tu puntualidad. Si no, echarás por tierra tu reputación.', 'https://en.wiktionary.org/wiki/echar_por_tierra#Spanish'), -- example: tatoeba.org/sentences/865053 (inmachan)
  ('quemar las naves', 'to burn one''s bridges', 'Se han quemado las naves y las posibilidades son escasas.', 'https://en.wiktionary.org/wiki/quemar_las_naves#Spanish'), -- example: tatoeba.org/sentences/1638189 (teskmon)
  ('faltaría más', 'don''t mention it; you''re welcome', '¿Puedo usar su teléfono? ¡No faltaría más!', 'https://en.wiktionary.org/wiki/faltaría_más#Spanish'), -- example: tatoeba.org/sentences/4987492 (saverius)
  ('nacer de pie', 'to be born lucky', 'Ese hombre nació de pie.', 'https://en.wiktionary.org/wiki/nacer_de_pie#Spanish'), -- example: tatoeba.org/sentences/2267862 (cueyayotl)
  ('echar en cara', 'to reproach', 'Se me echaba en cara que siempre llegara tarde.', 'https://en.wiktionary.org/wiki/echar_en_cara#Spanish'), -- example: tatoeba.org/sentences/5778723 (solmyrbcn)
  ('errar es humano', 'to err is human', 'Errar es humano, pero más lo es culpar de ello a otros.', 'https://en.wiktionary.org/wiki/errar_es_humano#Spanish'), -- example: tatoeba.org/sentences/3990723 (carlosalberto)
  ('echar a andar', 'to launch, set up, set in motion', 'No puedo echar a andar este motor. Está averiado.', 'https://en.wiktionary.org/wiki/echar_a_andar#Spanish'), -- example: tatoeba.org/sentences/1726753 (marcelostockle)
  ('a sus pies', 'at one''s feet', 'Pepe sentía que su vida se desmoronaba a sus pies.', 'https://en.wiktionary.org/wiki/a_sus_pies#Spanish'), -- example: tatoeba.org/sentences/1065121 (Shishir)
  ('no es oro todo lo que reluce', 'all that glitters is not gold', 'Ciertamente no es oro todo lo que reluce.', 'https://en.wiktionary.org/wiki/no_es_oro_todo_lo_que_reluce#Spanish'), -- example: tatoeba.org/sentences/5432630 (Seael)
  ('consultar con la almohada', 'to sleep on (make a decision after sleeping)', 'Creo que necesitas consultarlo primero con la almohada.', 'https://en.wiktionary.org/wiki/consultar_con_la_almohada#Spanish'), -- example: tatoeba.org/sentences/5033608 (don_ramon)
  ('poner en evidencia', 'to reveal, to highlight', '¡Eres una impostora y te voy a poner en evidencia delante de todos!', 'https://en.wiktionary.org/wiki/poner_en_evidencia#Spanish'), -- example: tatoeba.org/sentences/13521482 (Seael)
  ('me suena a chino', 'it''s all Greek to me; I don''t understand any of this', '"¿Usted entiende la asignatura?" "Ni papa. Todo me suena a chino."', 'https://en.wiktionary.org/wiki/me_suena_a_chino#Spanish'), -- example: tatoeba.org/sentences/1806056 (wallebot)
  ('el tiempo dirá', 'time will tell', 'Solo el tiempo dirá lo que el mundo tiene guardado para nosotros.', 'https://en.wiktionary.org/wiki/el_tiempo_dirá#Spanish'), -- example: tatoeba.org/sentences/9352259 (ecorralest101)
  ('qué tripa se te ha roto', 'what''s the matter; what''s with you', '¿Se puede saber qué tripa se te ha roto a ti ahora?', 'https://en.wiktionary.org/wiki/qué_tripa_se_te_ha_roto#Spanish'), -- example: tatoeba.org/sentences/13759510 (Seael)
  ('echar en falta', 'to miss, lack', 'No eché en falta mi monedero hasta que llegué a casa.', 'https://en.wiktionary.org/wiki/echar_en_falta#Spanish'), -- example: tatoeba.org/sentences/1271486 (Silvestre)
  ('devanarse los sesos', 'to rack one''s brains', 'Me estoy devanando los sesos para encontrar una solución.', 'https://en.wiktionary.org/wiki/devanarse_los_sesos#Spanish'), -- example: tatoeba.org/sentences/2267231 (cueyayotl)
  ('las paredes oyen', 'walls have ears', 'La historia de Edward Snowden nos ha recordado una vez más que hasta las paredes oyen.', 'https://en.wiktionary.org/wiki/las_paredes_oyen#Spanish'), -- example: tatoeba.org/sentences/2624707 (Shishir)
  ('predicar con el ejemplo', 'to lead by example; to practice what one preaches', 'Sócrates era un hombre que predicaba con el ejemplo.', 'https://en.wiktionary.org/wiki/predicar_con_el_ejemplo#Spanish'), -- example: tatoeba.org/sentences/13732393 (carlosalberto)
  ('sentar la cabeza', 'to get one''s act together', '¿No crees que ya va siendo hora de que sientes la cabeza?', 'https://en.wiktionary.org/wiki/sentar_la_cabeza#Spanish'), -- example: tatoeba.org/sentences/575481 (Shishir)
  ('dar en el blanco', 'to hit the target; to hit the nail on the head', 'Apunta demasiado bajo para dar en el blanco.', 'https://en.wiktionary.org/wiki/dar_en_el_blanco#Spanish'), -- example: tatoeba.org/sentences/2259962 (cueyayotl)
  ('quedar en agua de borrajas', 'to be put on hold; to not be fulfilled', 'Espero que todo quede al final en agua de borrajas.', 'https://en.wiktionary.org/wiki/quedar_en_agua_de_borrajas#Spanish'), -- example: tatoeba.org/sentences/10559225 (Seael)
  ('buscar pelos en la sopa', 'to look for excuses to complain', 'Siempre buscas pelos en la sopa.', 'https://en.wiktionary.org/wiki/buscar_pelos_en_la_sopa#Spanish'), -- example: Wiktionary
  ('hacer oídos sordos', 'to turn a deaf ear', 'Mi padre hizo oídos sordos a mis peticiones.', 'https://en.wiktionary.org/wiki/hacer_oídos_sordos#Spanish'), -- example: tatoeba.org/sentences/1205665 (marcelostockle)
  ('ahogar las penas', 'to drown one''s sorrows', 'Creo que voy a tomar un vaso de vino para ahogar las penas.', 'https://en.wiktionary.org/wiki/ahogar_las_penas#Spanish'), -- example: tatoeba.org/sentences/3975681 (hayastan)
  ('no ver la hora de', 'to look forward to; can''t wait (for)', '¡No veo la hora de que nos casemos!', 'https://en.wiktionary.org/wiki/no_ver_la_hora_de#Spanish'), -- example: Wiktionary
  ('ir a misa', 'to be undisputed, to be indisputable, to be undeniable', 'Yo soy quien manda aquí, y lo que yo digo va a misa.', 'https://en.wiktionary.org/wiki/ir_a_misa#Spanish'), -- example: Wiktionary
  ('jugar con fuego', 'to play with fire', 'Es por eso mismo que nadie debería jugar con fuego.', 'https://en.wiktionary.org/wiki/jugar_con_fuego#Spanish'), -- example: tatoeba.org/sentences/10205233 (Shishir)
  ('al fin y al cabo', 'when all is said and done', 'Me llevaron al doctor, al fin y al cabo no tenía nada.', 'https://en.wiktionary.org/wiki/al_fin_y_al_cabo#Spanish'), -- example: tatoeba.org/sentences/3608176 (karo)
  ('llegar a fin de mes', 'to make ends meet', 'Hace ya más de medio año que no llegamos a fin de mes.', 'https://en.wiktionary.org/wiki/llegar_a_fin_de_mes#Spanish'), -- example: tatoeba.org/sentences/11708159 (Seael)
  ('empezar la casa por el tejado', 'to put the cart before the horse', 'No hay que empezar la casa por el tejado.', 'https://en.wiktionary.org/wiki/empezar_la_casa_por_el_tejado#Spanish'), -- example: tatoeba.org/sentences/1303349 (enteka)
  ('tomar cartas en el asunto', 'to step in, stand in', 'Tom decidió tomar cartas en el asunto.', 'https://en.wiktionary.org/wiki/tomar_cartas_en_el_asunto#Spanish'), -- example: tatoeba.org/sentences/1131293 (marcelostockle)
  ('hacer la vista gorda', 'to turn a blind eye, to shut one''s eyes, to look the other way', '¿No te parece que Olga ha hecho la vista gorda en este asunto?', 'https://en.wiktionary.org/wiki/hacer_la_vista_gorda#Spanish'), -- example: tatoeba.org/sentences/10227305 (Seael)
  ('armar la de san Quintín', 'to start a fight', '¡Menuda pelea se formó en el bar! Se armó la de San Quintín.', 'https://en.wiktionary.org/wiki/armar_la_de_san_Quintín#Spanish'), -- example: tatoeba.org/sentences/1723378 (teskmon)
  ('echar con cajas destempladas', 'to kick out; send packing', 'Era un engañabobos al que echamos de casa con cajas destempladas.', 'https://en.wiktionary.org/wiki/echar_con_cajas_destempladas#Spanish'), -- example: tatoeba.org/sentences/13513485 (Seael)
  ('todos los caminos llevan a Roma', 'all roads lead to Rome', 'Todos los caminos llevan a Roma, pero ninguno a tu corazón.', 'https://en.wiktionary.org/wiki/todos_los_caminos_llevan_a_Roma#Spanish'), -- example: tatoeba.org/sentences/10143662 (saverius)
  ('morder el polvo', 'to bite the dust', 'Tom está a punto de morder el polvo.', 'https://en.wiktionary.org/wiki/morder_el_polvo#Spanish'), -- example: tatoeba.org/sentences/5566716 (swyter)
  ('dar la espalda', 'to turn one''s back; to refuse to help or aid somebody', 'Él nunca da la espalda a un amigo que necesita ayuda.', 'https://en.wiktionary.org/wiki/dar_la_espalda#Spanish'), -- example: tatoeba.org/sentences/748711 (darinmex)
  ('caerse de un guindo', 'to be born yesterday', '¿Crees que me he caído de un guindo ahora?', 'https://en.wiktionary.org/wiki/caerse_de_un_guindo#Spanish'), -- example: Wiktionary
  ('jugarse el tipo', 'to risk life and limb; to risk one''s neck', '¡Aurora, dile algo! ¿No ves que se está jugando el tipo por ti por una cosa que te la trae al fresco?', 'https://en.wiktionary.org/wiki/jugarse_el_tipo#Spanish'), -- example: tatoeba.org/sentences/10465059 (Shishir)
  ('tener la sartén por el mango', 'to call the shots', 'Quien tiene el oro, tiene la sartén por el mango.', 'https://en.wiktionary.org/wiki/tener_la_sartén_por_el_mango#Spanish'), -- example: tatoeba.org/sentences/5539636 (ecorralest101)
  ('pillar el toro', 'to miss the boat; to run out of time', 'Vete preparándote, no te vaya a pillar luego el toro.', 'https://en.wiktionary.org/wiki/pillar_el_toro#Spanish'), -- example: tatoeba.org/sentences/11964307 (Seael)
  ('tener a bien', 'to see fit', 'Tengo a bien recibirlo.', 'https://en.wiktionary.org/wiki/tener_a_bien#Spanish'), -- example: tatoeba.org/sentences/5105253 (ecorralest101)
  ('cambiar de manos', 'to change hands; to be bought or sold or to change ownership', 'Ese edificio ha cambiado de manos muchas veces.', 'https://en.wiktionary.org/wiki/cambiar_de_manos#Spanish'), -- example: tatoeba.org/sentences/1685368 (Elenitigormiti)
  ('quedarse con la copla', 'to understand; to know the score; to get with the program', '¿Te has quedado con la copla de todo?', 'https://en.wiktionary.org/wiki/quedarse_con_la_copla#Spanish'), -- example: Wiktionary
  ('llevar los pantalones', 'to wear the pants, to wear the trousers', '¿En tu casa quién lleva los pantalones?', 'https://en.wiktionary.org/wiki/llevar_los_pantalones#Spanish'), -- example: tatoeba.org/sentences/661931 (Shishir)
  ('tener sin cuidado', 'to not bother', 'A Tom lo tiene sin cuidado lo que se piensa de él.', 'https://en.wiktionary.org/wiki/tener_sin_cuidado#Spanish'), -- example: tatoeba.org/sentences/3769534 (IXTLA)
  ('faltar a la cita', 'to miss out', 'No puede usted faltar a la cita.', 'https://en.wiktionary.org/wiki/faltar_a_la_cita#Spanish'), -- example: tatoeba.org/sentences/2270608 (cueyayotl)
  ('parar los pies', 'to stop (someone) in their tracks', 'Alguien debería pararle los pies.', 'https://en.wiktionary.org/wiki/parar_los_pies#Spanish'), -- example: tatoeba.org/sentences/13076521 (arh)
  ('salirse de madre', 'to spiral out of control', 'Esto se está saliendo de madre.', 'https://en.wiktionary.org/wiki/salirse_de_madre#Spanish'), -- example: tatoeba.org/sentences/2413401 (Shishir)
  ('dulces sueños', 'sweet dreams', 'Sin un beso de buenas noches no tendré dulces sueños.', 'https://en.wiktionary.org/wiki/dulces_sueños#Spanish'), -- example: tatoeba.org/sentences/4984159 (Shishir)
  ('hacerse el tonto', 'to play the fool', 'No te hagas el tonto, sabes muy bien de qué estoy hablando.', 'https://en.wiktionary.org/wiki/hacerse_el_tonto#Spanish'), -- example: tatoeba.org/sentences/9770371 (arh)
  ('dar cien vueltas', 'to brood on, to chew on, to mull over, to go over', 'Sabes que Timotea te da cien vueltas dialécticamente.', 'https://en.wiktionary.org/wiki/dar_cien_vueltas#Spanish'), -- example: tatoeba.org/sentences/11932401 (Seael)
  ('echarle los perros', 'to flirt', 'Ella siempre estaba echándole los perros a Mauricio.', 'https://en.wiktionary.org/wiki/echarle_los_perros#Spanish'), -- example: Wiktionary
  ('pasarse tres pueblos', 'to go too far, go past the limit', 'Tomasa se está pasando tres pueblos con esa afirmación.', 'https://en.wiktionary.org/wiki/pasarse_tres_pueblos#Spanish'), -- example: tatoeba.org/sentences/13636113 (Seael)
  ('el tiempo vuela', 'time flies', 'A menudo escuchamos a la gente decir que el tiempo vuela.', 'https://en.wiktionary.org/wiki/el_tiempo_vuela#Spanish'), -- example: tatoeba.org/sentences/3073788 (cueyayotl)
  ('salir a cuenta', 'to pay off; to be worthwhile', 'Me sale más a cuenta comprar un billete de ida y vuelta que uno solo de ida.', 'https://en.wiktionary.org/wiki/salir_a_cuenta#Spanish'), -- example: tatoeba.org/sentences/1238642 (wallebot)
  ('quitarse un peso de encima', 'to get off one''s chest', '¡Ah, qué alivio! Me quité un peso de encima gigante.', 'https://en.wiktionary.org/wiki/quitarse_un_peso_de_encima#Spanish'), -- example: tatoeba.org/sentences/10939619 (Adelpa)
  ('trabarse la lengua', 'to become tongue-tied', 'Se me trababa la lengua cuando ella me habló.', 'https://en.wiktionary.org/wiki/trabarse_la_lengua#Spanish'), -- example: tatoeba.org/sentences/569585 (winice)
  ('no hay peor ciego que el que no quiere ver', 'there are none so blind as those who will not see', 'No ves que te está timando. ¡No hay peor ciego que el que no quiere ver!', 'https://en.wiktionary.org/wiki/no_hay_peor_ciego_que_el_que_no_quiere_ver#Spanish'), -- example: tatoeba.org/sentences/1618407 (teskmon)
  ('echar a la calle', 'to dismiss or fire someone', 'No tuve más remedio que echarle a la calle.', 'https://en.wiktionary.org/wiki/echar_a_la_calle#Spanish'), -- example: tatoeba.org/sentences/2258773 (SrTortuga)
  ('caerle una buena', 'to be in for it; to be in serious trouble', 'Te va a caer una buena cuando vuelvas a casa.', 'https://en.wiktionary.org/wiki/caerle_una_buena#Spanish'), -- example: Wiktionary
  ('valer la pena', 'to be worth the effort, to pay off', 'Por lo general, vale la pena jugar el juego de la vida.', 'https://en.wiktionary.org/wiki/valer_la_pena#Spanish'), -- example: tatoeba.org/sentences/1277933 (marcelostockle)
  ('hablando del rey de Roma', 'speak of the devil', 'Hablando del rey de Roma ..., por la puerta asoma.', 'https://en.wiktionary.org/wiki/hablando_del_rey_de_Roma#Spanish'), -- example: tatoeba.org/sentences/9012912 (arh)
  ('leer entre líneas', 'to read between the lines', 'Pude leer entre líneas que él quería que yo renunciara.', 'https://en.wiktionary.org/wiki/leer_entre_líneas#Spanish'), -- example: tatoeba.org/sentences/972150 (hundo)
  ('el amor es ciego', 'love is blind', 'El amor es ciego, el águila se casó con un cuervo.', 'https://en.wiktionary.org/wiki/el_amor_es_ciego#Spanish'), -- example: tatoeba.org/sentences/11027535 (JSKabylie)
  ('salir a la luz', 'to come to light', 'La verdad finalmente salió a la luz durante su juicio.', 'https://en.wiktionary.org/wiki/salir_a_la_luz#Spanish'), -- example: tatoeba.org/sentences/1935068 (marinoli)
  ('lo que me faltaba', 'that''s all I needed!', '"Aquí viene Tom." "¡Genial, es justo lo que me faltaba!"', 'https://en.wiktionary.org/wiki/lo_que_me_faltaba#Spanish'), -- example: tatoeba.org/sentences/10260216 (DJ_Saidez)
  ('sacar de sus casillas', 'to drive up the wall, get a rise out of', 'El irritante tintineo metálico no tardó en empezar a sacarla de sus casillas.', 'https://en.wiktionary.org/wiki/sacar_de_sus_casillas#Spanish'), -- example: tatoeba.org/sentences/11684472 (Seael)
  ('mañana será otro día', 'tomorrow is another day', 'Ahora descansa. Mañana será otro día.', 'https://en.wiktionary.org/wiki/mañana_será_otro_día#Spanish'), -- example: tatoeba.org/sentences/11858156 (Seael)
  ('traer al fresco', 'to not mind, couldn''t care less', 'A Timotea lo que pensemos se la trae al fresco.', 'https://en.wiktionary.org/wiki/traer_al_fresco#Spanish'), -- example: tatoeba.org/sentences/11932399 (Seael)
  ('ya que estoy', 'while one is at it', 'Ya que estoy aquí, déjame ayudarte.', 'https://en.wiktionary.org/wiki/ya_que_estoy#Spanish'), -- example: tatoeba.org/sentences/1715622 (marcelostockle)
  ('sacar lo mejor de', 'to make the best of', 'Roberto sacó lo mejor de Jack en ese partido de ajedrez.', 'https://en.wiktionary.org/wiki/sacar_lo_mejor_de#Spanish'), -- example: tatoeba.org/sentences/862621 (Ajedrez)
  ('callar la boca', 'to shut one''s mouth; to shut up', 'Dijo que no se lo debía contar a nadie. Por lo tanto callé la boca.', 'https://en.wiktionary.org/wiki/callar_la_boca#Spanish'), -- example: tatoeba.org/sentences/1678677 (termito2nd)
  ('ganarse la vida', 'to make a living', 'Ganarse la vida como artista de mangas es casi imposible.', 'https://en.wiktionary.org/wiki/ganarse_la_vida#Spanish'), -- example: tatoeba.org/sentences/1291812 (marcelostockle)
  ('ir de mal en peor', 'to go from bad to worse; to worsen', 'Las cosas parecen ir de mal en peor.', 'https://en.wiktionary.org/wiki/ir_de_mal_en_peor#Spanish'), -- example: tatoeba.org/sentences/1493337 (Shishir)
  ('dar las uvas', 'to cause to take a long time or to go slowly', '¡Nos van a dar las uvas esperando!', 'https://en.wiktionary.org/wiki/dar_las_uvas#Spanish'), -- example: Wiktionary
  ('de tal palo, tal astilla', 'chip off the old block, the apple doesn''t fall far from the tree', 'Si es que, de tal palo, tal astilla.', 'https://en.wiktionary.org/wiki/de_tal_palo,_tal_astilla#Spanish'), -- example: tatoeba.org/sentences/9841499 (arh)
  ('echar un cable', 'to lend a hand', 'No creo que Daniel vaya a poder echarnos un cable.', 'https://en.wiktionary.org/wiki/echar_un_cable#Spanish'), -- example: tatoeba.org/sentences/13675115 (Seael)
  ('cuando el río suena, agua lleva', 'there''s no smoke without fire', '"Es sólo una estúpida leyenda urbana." "Pero... cuando el río suena, agua lleva."', 'https://en.wiktionary.org/wiki/cuando_el_río_suena,_agua_lleva#Spanish'), -- example: tatoeba.org/sentences/8390228 (ManuelML)
  ('poner de los nervios', 'to get on someone''s nerves; to grate on; to put on edge', 'En el trabajo hay un idiota que me pone de los nervios.', 'https://en.wiktionary.org/wiki/poner_de_los_nervios#Spanish'), -- example: tatoeba.org/sentences/13698396 (Seael)
  ('pasar por alto', 'to overlook', 'No podemos pasar por alto un comentario tan incendiario.', 'https://en.wiktionary.org/wiki/pasar_por_alto#Spanish'), -- example: tatoeba.org/sentences/10849900 (Seael)
  ('estar de capa caída', 'to be crestfallen; to be down in the dumps', 'El comercio está de capa caída.', 'https://en.wiktionary.org/wiki/estar_de_capa_caída#Spanish'), -- example: tatoeba.org/sentences/1323509 (massama)
  ('nadar y guardar la ropa', 'have one''s cake and eat it', 'No se puede nadar y guardar la ropa.', 'https://en.wiktionary.org/wiki/nadar_y_guardar_la_ropa#Spanish'), -- example: tatoeba.org/sentences/5484456 (ecorralest101)
  ('estar al loro', 'to watch out; to keep an eye out', 'Estate al loro y no pierdas comba.', 'https://en.wiktionary.org/wiki/estar_al_loro#Spanish'), -- example: tatoeba.org/sentences/13662381 (Seael)
  ('manos a la obra', 'hands on deck, let''s get to work, let''s get to it, get down to work, get on with it, get down to business', 'Tenemos que ponernos manos a la obra cuanto antes.', 'https://en.wiktionary.org/wiki/manos_a_la_obra#Spanish'), -- example: tatoeba.org/sentences/11686635 (Seael)
  ('adivina qué', 'guess what', '¡Adivina qué! Me voy a estudiar a Nueva Zelanda.', 'https://en.wiktionary.org/wiki/adivina_qué#Spanish'), -- example: tatoeba.org/sentences/1603713 (marcelostockle)
  ('perder el norte', 'to lose the plot', 'Ha perdido el Norte, ya no sabe ni donde está parada.', 'https://en.wiktionary.org/wiki/perder_el_norte#Spanish'), -- example: tatoeba.org/sentences/9742305 (JSKabylie)
  ('más se perdió en Cuba', 'worse things happen at sea; could be worse; things ain''t as bad as they might be', 'No te preocupes, más se perdió en Cuba.', 'https://en.wiktionary.org/wiki/más_se_perdió_en_Cuba#Spanish'), -- example: tatoeba.org/sentences/5372748 (capiscuas)
  ('poner los cuernos', 'to cheat on, put horns on', 'Se puso furioso cuando descubrió que su mujer le estaba poniendo los cuernos.', 'https://en.wiktionary.org/wiki/poner_los_cuernos#Spanish'), -- example: Wiktionary
  ('pasarse el arroz', 'to be over the hill, to be past one''s prime', 'Se te ha pasado el arroz.', 'https://en.wiktionary.org/wiki/pasarse_el_arroz#Spanish') -- example: Wiktionary
